package com.example.floodmonitor.service;
import com.example.floodmonitor.model.*;
import com.example.floodmonitor.repository.StationRepository;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import jakarta.annotation.PostConstruct;
import java.time.*;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;
import java.util.stream.*;
@Service public class FloodService {
 private final StationRepository repo;
 public FloodService(StationRepository repo){this.repo=repo;}
 public WarningLevel level(Station s,double water){if(!Double.isFinite(water)||water<0)return WarningLevel.UNKNOWN; if(water>=s.criticalWaterLevel())return WarningLevel.CRITICAL;if(water>=s.warningWaterLevel())return WarningLevel.WARNING;return WarningLevel.NORMAL;}
 @PostConstruct public void init(){for(Station s:repo.stations.values()){double start=s.warningWaterLevel()+(s.id().equals("ST-003")?90:s.id().equals("ST-002")?10:-35);for(int i=20;i>=0;i--) {double water=Math.max(0,start-i*.7);Measurement m=new Measurement(s.id(),Instant.now().minusSeconds(i*60),water,water*1.85,Math.max(0,4+i%5),17,95,StationStatus.ONLINE,level(s,water));repo.measurements.get(s.id()).add(m);}}}
 @Scheduled(fixedDelayString="${simulation.interval:10000}") public void tick(){for(Station s:repo.stations.values()){if(!s.isActive())continue;List<Measurement> list=repo.measurements.get(s.id());Measurement last=list.isEmpty()?null:list.get(list.size()-1);if(last!=null&&last.status()!=StationStatus.ONLINE)continue;ThreadLocalRandom r=ThreadLocalRandom.current();double rain=r.nextDouble(0,18);double previous=last==null?s.normalWaterLevel():last.waterLevel();double water=Math.max(0,previous+(rain-7)*.27+r.nextDouble(-1.5,1.5));int battery=last==null?100:Math.max(0,last.batteryLevel()-(r.nextInt(12)==0?1:0));StationStatus status=battery<5?StationStatus.MAINTENANCE:StationStatus.ONLINE;list.add(new Measurement(s.id(),Instant.now(),round(water),round(water*1.85+r.nextDouble(0,12)),round(rain),round(r.nextDouble(5,26)),battery,status,level(s,water)));if(list.size()>2000)list.remove(0);}}
 private double round(double v){return Math.round(v*100.0)/100.0;}
 public Station station(String id){Station s=repo.stations.get(id);if(s==null)throw new NoSuchElementException("Station "+id+" wurde nicht gefunden");return s;}
 public List<Station> stations(String river,Boolean active,WarningLevel level){return repo.stations.values().stream().filter(s->river==null||s.river().equalsIgnoreCase(river)).filter(s->active==null||s.isActive()==active).filter(s->level==null||latestLevel(s.id())==level).sorted(Comparator.comparing(Station::id)).toList();}
 public WarningLevel latestLevel(String id){List<Measurement> l=repo.measurements.get(id);return l==null||l.isEmpty()?WarningLevel.UNKNOWN:l.get(l.size()-1).warningLevel();}
 public Measurement latest(String id){station(id);List<Measurement> l=repo.measurements.get(id);if(l.isEmpty())throw new NoSuchElementException("Keine Messung für "+id);return l.get(l.size()-1);}
 public List<Measurement> history(String id,Instant from,Instant to,Integer limit,WarningLevel level){station(id);if(from!=null&&to!=null&&from.isAfter(to))throw new IllegalArgumentException("from darf nicht nach to liegen");if(limit!=null&&(limit<1||limit>1000))throw new IllegalArgumentException("limit muss zwischen 1 und 1000 liegen");return repo.measurements.get(id).stream().filter(m->from==null||!m.timestamp().isBefore(from)).filter(m->to==null||!m.timestamp().isAfter(to)).filter(m->level==null||m.warningLevel()==level).sorted(Comparator.comparing(Measurement::timestamp).reversed()).limit(limit==null?100:limit).toList();}
 public List<Alert> alerts(WarningLevel level,String river){return repo.stations.values().stream().filter(s->river==null||s.river().equalsIgnoreCase(river)).map(s-> {Measurement m=latest(s.id());return new Alert(s.id(),s.river(),m.timestamp(),m.warningLevel(),m.waterLevel());}).filter(a->a.warningLevel()==WarningLevel.WARNING||a.warningLevel()==WarningLevel.CRITICAL).filter(a->level==null||a.warningLevel()==level).sorted(Comparator.comparing(Alert::stationId)).toList();}
 public Statistics statistics(String id,Instant from,Instant to){List<Measurement> l=history(id,from,to,1000,null);if(l.isEmpty())return new Statistics(0,0,0,0,0,0,0,0);DoubleSummaryStatistics w=l.stream().mapToDouble(Measurement::waterLevel).summaryStatistics();return new Statistics(w.getMin(),w.getMax(),w.getAverage(),l.stream().mapToDouble(Measurement::flowRate).average().orElse(0),l.stream().mapToDouble(Measurement::rainfall).sum(),l.size(),l.stream().filter(m->m.warningLevel()==WarningLevel.WARNING).count(),l.stream().filter(m->m.warningLevel()==WarningLevel.CRITICAL).count());}
 public Station create(Station s){validate(s);if(repo.stations.containsKey(s.id()))throw new IllegalStateException("Station existiert bereits");repo.add(s);return s;}
 public Station update(String id,Map<String,Object> changes){Station s=station(id);for(String key:changes.keySet())if(!Set.of("name","river","isActive","normalWaterLevel","warningWaterLevel","criticalWaterLevel").contains(key))throw new IllegalArgumentException("Unbekanntes Feld: "+key);try{Station updated=new Station(id,(String)changes.getOrDefault("name",s.name()),(String)changes.getOrDefault("river",s.river()),s.location(),num(changes,"normalWaterLevel",s.normalWaterLevel()),num(changes,"warningWaterLevel",s.warningWaterLevel()),num(changes,"criticalWaterLevel",s.criticalWaterLevel()),(Boolean)changes.getOrDefault("isActive",s.isActive()));validate(updated);repo.stations.put(id,updated);return updated;}catch(ClassCastException e){throw new IllegalArgumentException("Ungültiger Feldtyp");}}
 private double num(Map<String,Object> m,String k,double fallback){Object v=m.get(k);if(v==null)return fallback;if(!(v instanceof Number))throw new IllegalArgumentException("Ungültiger Zahlenwert: "+k);return ((Number)v).doubleValue();}
 private void validate(Station s){if(s==null||s.id()==null||s.id().isBlank()||s.name()==null||s.name().isBlank()||s.river()==null||s.river().isBlank()||s.location()==null||s.normalWaterLevel()<0||s.warningWaterLevel()<=s.normalWaterLevel()||s.criticalWaterLevel()<=s.warningWaterLevel()||!Double.isFinite(s.criticalWaterLevel())||Math.abs(s.location().latitude())>90||Math.abs(s.location().longitude())>180)throw new IllegalArgumentException("Ungültige Stationsdaten oder Grenzwerte");}
 public void delete(String id){station(id);repo.stations.remove(id);repo.measurements.remove(id);}
}